import{_ as t,o as s,c as n,a2 as a}from"./chunks/framework.BBXLvvRa.js";const o="/img/bpm-lifecycle.png",m=JSON.parse('{"title":"Fostering Business-IT Alignment","description":"Keep automated processes anchored in a shared understanding of the business domain, so the people who run them can read, question, and correct the model.","frontmatter":{"title":"Fostering Business-IT Alignment","description":"Keep automated processes anchored in a shared understanding of the business domain, so the people who run them can read, question, and correct the model."},"headers":[],"relativePath":"docs/principles/business-it-alignment.md","filePath":"docs/principles/business-it-alignment.md"}'),i={name:"docs/principles/business-it-alignment.md"};function r(l,e,d,c,h,u){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="fostering-business-it-alignment" tabindex="-1">Fostering Business-IT Alignment <a class="header-anchor" href="#fostering-business-it-alignment" aria-label="Permalink to &quot;Fostering Business-IT Alignment&quot;">​</a></h1><blockquote><p>Fostering Business-IT Alignment <strong>over</strong> Developer-driven Process Automation</p></blockquote><p><em>A process you automate should be a process your business can read, question, and correct.</em></p><p>This principle asserts that process automation succeeds when business and IT build a shared understanding of the domain, not when developers translate requirements into code on their own. We hold this because a model is only as valuable as the real-world process it represents. When the people who run the process can read the model, the model stays honest.</p><p>Alignment is not a one-time handover. It runs through the whole BPM lifecycle: a process moves from identification and discovery, through analysis and redesign, into implementation, monitoring, and controlling, and then round again. Business and IT meet at every stage, and the process model is the shared artifact that carries understanding from one stage to the next.</p><p><img src="'+o+'" alt="The BPM lifecycle, a loop of six phases: process identification, process discovery, process analysis, process redesign, process implementation, and process monitoring and controlling."></p><p><em>The BPM lifecycle, after Dumas, La Rosa, Mendling, and Reijers, <a href="https://link.springer.com/book/10.1007/978-3-662-56509-4" target="_blank" rel="noreferrer">Fundamentals of Business Process Management</a> (Springer, 2018).</em></p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>When your developers own a process in isolation, the running model drifts from the business it serves. Picture a claims-approval process that encodes an engineer&#39;s assumptions about escalation rules no adjuster ever confirmed. You do not see the gap until it surfaces in production as rework, workarounds, and lost trust.</p><p>BPMN (Business Process Model and Notation, the standard graphical language for process diagrams) is built to be read by non-technical stakeholders. You lose that value when your diagram fills up with technical detail. An unreadable model stops being a communication artifact and becomes an execution artifact alone: code in another shape.</p><p>The concrete costs show up again and again:</p><ul><li><strong>Knowledge concentrates.</strong> Process expertise lives in one or two developers and leaves when they do.</li><li><strong>Stakeholders sign off on the wrong thing.</strong> They approve documents rather than the model that runs, so nobody validates what actually executes.</li><li><strong>Terminology diverges.</strong> &quot;Customer&quot; in your model means something different from &quot;customer&quot; to the business, which quietly breaks decision logic and reporting.</li></ul><h2 id="in-practice" tabindex="-1">In practice <a class="header-anchor" href="#in-practice" aria-label="Permalink to &quot;In practice&quot;">​</a></h2><ul><li><strong>Model together, not for.</strong> Run collaborative modeling sessions with domain experts instead of handing them a finished model to rubber-stamp. A tangible method such as <a href="https://www.researchgate.net/figure/the-TBPM-toolkit-and-table_fig5_266278417" target="_blank" rel="noreferrer">t.BPM</a>, which lays out physical BPMN tiles on a table, draws non-technical participants into the modeling and produces a model everyone has helped shape.</li><li><strong>Keep the top level readable.</strong> Push connectors, error handling, and expressions into subprocesses or call activities so the main diagram still tells the business story.</li><li><strong>Establish a ubiquitous language.</strong> Agree on one shared set of terms for tasks, roles, and data (a ubiquitous language, in domain-driven design terms), then reuse it in BPMN element names, DMN inputs, process variables, and gateway labels so every element reads the way the business speaks.</li><li><strong>Externalize decisions with DMN.</strong> Move business rules out of code into DMN (Decision Model and Notation) decision tables that domain experts can read and change without a deployment.</li><li><strong>Validate the executable model itself.</strong> Walk stakeholders through the actual deployable model in Camunda, Operaton, or Flowable, not a separate specification that drifts from it.</li></ul><h2 id="what-this-doesn-t-mean" tabindex="-1">What this doesn&#39;t mean <a class="header-anchor" href="#what-this-doesn-t-mean" aria-label="Permalink to &quot;What this doesn&#39;t mean&quot;">​</a></h2><p>This is not a call to stop writing code or to let non-technical stakeholders drive every technical decision. Developer-driven automation delivers real value: engineers bring the discipline, integration skill, and depth that make a model executable and reliable. The point is one of emphasis and sequencing: ground the work in shared domain understanding first, so the code you write automates the process the business actually runs.</p><h2 id="related-principles" tabindex="-1">Related principles <a class="header-anchor" href="#related-principles" aria-label="Permalink to &quot;Related principles&quot;">​</a></h2><ul><li><a href="/docs/principles/best-practices">Process Automation Best Practices</a>: readable modeling conventions and separating orchestration from business logic keep aligned models maintainable.</li><li><a href="/docs/principles/continuous-improvement">Continuous Process Improvement</a>: shared alignment feeds the improvement loop, with the business tuning DMN tables over time.</li></ul>',18)])])}const g=t(i,[["render",r]]);export{m as __pageData,g as default};
